        {
          "text": "Declare a boolean variable `hasCriminalRecord` and set it to false.",
          "refs": ["Q0000"]
        },
        {
          "text": "Wrap the existing high‑income‑or‑good‑credit expression in parentheses.",
          "refs": ["Q0000"]
        },
        {
          "text": "Combine the wrapped expression with `hasCriminalRecord` using the AND operator (`&&`).",
          "refs": ["Q0000"]
        },
        {
          "text": "Apply the NOT operator (`!`) to `hasCriminalRecord` so the combined condition requires no criminal record.",
          "refs": ["Q0001"]
        }
      ],
